package smp.aeternum.carpet.client;

import java.util.*;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;
import net.minecraft.client.gl.RenderPipelines;
import net.minecraft.client.gui.DrawContext;
import net.minecraft.client.gui.screen.Screen;
import net.minecraft.client.gui.widget.ButtonWidget;
import net.minecraft.client.texture.NativeImage;
import net.minecraft.client.texture.NativeImageBackedTexture;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;
import smp.aeternum.carpet.network.*;

/** Server-authoritative, one-pixel-per-block map. Textures are temporary and freed on close. */
final class ExplorationMapScreen extends Screen {
 private static final int TILE=128; private final List<ExplorationMapOpenPayload.Area> areas; private final Map<Key,Identifier> tiles=new HashMap<>(); private final Set<Key> requested=new HashSet<>();
 private String dimension; private double centerX,centerZ,zoom=1; private boolean dragging,showChunkGrid=true,showRegionGrid=true;private double lastX,lastY; private ButtonWidget chunkGridButton,regionGridButton;
 ExplorationMapScreen(ExplorationMapOpenPayload d){super(Text.literal("Mapa de exploración"));dimension=d.dimension();centerX=d.centerChunkX()*16.0;centerZ=d.centerChunkZ()*16.0;areas=d.areas();}
 @Override protected void init(){int y=height-28;addDrawableChild(ButtonWidget.builder(Text.literal("Overworld"),b->dimension("minecraft:overworld")).dimensions(12,y,92,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("Nether"),b->dimension("minecraft:the_nether")).dimensions(108,y,72,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("End"),b->dimension("minecraft:the_end")).dimensions(184,y,56,20).build());chunkGridButton=ButtonWidget.builder(Text.literal("Chunks: sí"),b->{showChunkGrid=!showChunkGrid;updateGridButtons();}).dimensions(244,y,88,20).build();regionGridButton=ButtonWidget.builder(Text.literal("Regiones: sí"),b->{showRegionGrid=!showRegionGrid;updateGridButtons();}).dimensions(336,y,96,20).build();addDrawableChild(chunkGridButton);addDrawableChild(regionGridButton);addDrawableChild(ButtonWidget.builder(Text.literal("Cerrar"),b->close()).dimensions(width-82,y,70,20).build());}
 private void updateGridButtons(){chunkGridButton.setMessage(Text.literal("Chunks: "+(showChunkGrid?"sí":"no")));regionGridButton.setMessage(Text.literal("Regiones: "+(showRegionGrid?"sí":"no")));}
 private void dimension(String d){if(dimension.equals(d))return;clear();dimension=d;centerX=centerZ=0;zoom=1;}
 void accept(ExplorationMapTilePayload p){if(!p.dimension().equals(dimension)||p.colors().length!=TILE*TILE)return;Key k=new Key(p.dimension(),p.regionX(),p.regionZ());Identifier old=tiles.remove(k);if(old!=null)client.getTextureManager().destroyTexture(old);NativeImage image=new NativeImage(TILE,TILE,false);for(int z=0;z<TILE;z++)for(int x=0;x<TILE;x++)image.setColorArgb(x,z,p.colors()[z*TILE+x]);NativeImageBackedTexture texture=new NativeImageBackedTexture(()->"aeternum-map",image);texture.setFilter(false,false);texture.setClamp(true);Identifier id=Identifier.of("aeternum-carpet","map/"+Integer.toUnsignedString(k.hashCode()));client.getTextureManager().registerTexture(id,texture);tiles.put(k,id);requested.remove(k);}
 @Override public void renderBackground(DrawContext c,int x,int y,float d){}
 @Override public void render(DrawContext c,int mx,int my,float d){c.fill(0,0,width,height,0xE0101010);int l=10,t=28,r=width-10,b=height-36,cx=(l+r)/2,cy=(t+b)/2;c.fill(l,t,r,b,0xFF20242A);request(l,t,r,b,cx,cy);for(var e:tiles.entrySet()){Key k=e.getKey();if(!k.dimension.equals(dimension))continue;int x=(int)Math.floor(cx+(k.x*TILE-centerX)*zoom),y=(int)Math.floor(cy+(k.z*TILE-centerZ)*zoom),x2=(int)Math.ceil(x+TILE*zoom),y2=(int)Math.ceil(y+TILE*zoom);if(x2>l&&x<r&&y2>t&&y<b)c.drawTexture(RenderPipelines.GUI_TEXTURED,e.getValue(),x,y,0,0,x2-x,y2-y,TILE,TILE,TILE,TILE);}grid(c,l,t,r,b,cx,cy);areas(c,l,t,r,b,cx,cy);c.drawBorder(l,t,r-l,b-t,0xFF909090);int wx=(int)Math.floor(centerX+(mx-cx)/zoom),wz=(int)Math.floor(centerZ+(my-cy)/zoom),chunkX=Math.floorDiv(wx,16),chunkZ=Math.floorDiv(wz,16),regionX=Math.floorDiv(chunkX,32),regionZ=Math.floorDiv(chunkZ,32);c.drawTextWithShadow(textRenderer,"MAPA DE EXPLORACIÓN · "+dimension.substring(dimension.indexOf(':')+1).toUpperCase(),16,10,0xFFFFFFFF);c.drawTextWithShadow(textRenderer,"Bloque "+wx+", "+wz+" · Chunk "+chunkX+", "+chunkZ+" · Región "+regionX+", "+regionZ+" | "+String.format(Locale.ROOT,"%.3fx",zoom),width-430,10,0xFFAAAAAA);c.drawTextWithShadow(textRenderer,"Arrastra · rueda: zoom · Espacio: 0,0 · F: tu posición",16,height-51,0xFFAAAAAA);super.render(c,mx,my,d);}
 private void request(int l,int t,int r,int b,int cx,int cy){if(requested.size()>=2)return;int minX=(int)Math.floor(centerX+(l-cx)/zoom),maxX=(int)Math.ceil(centerX+(r-cx)/zoom),minZ=(int)Math.floor(centerZ+(t-cy)/zoom),maxZ=(int)Math.ceil(centerZ+(b-cy)/zoom),crx=Math.floorDiv((int)centerX,TILE),crz=Math.floorDiv((int)centerZ,TILE);List<Key> todo=new ArrayList<>();for(int z=Math.floorDiv(minZ,TILE);z<=Math.floorDiv(maxZ,TILE);z++)for(int x=Math.floorDiv(minX,TILE);x<=Math.floorDiv(maxX,TILE);x++){Key k=new Key(dimension,x,z);if(!tiles.containsKey(k)&&!requested.contains(k))todo.add(k);}todo.sort(Comparator.comparingInt(k->Math.abs(k.x-crx)+Math.abs(k.z-crz)));for(Key k:todo){if(requested.size()>=2)break;requested.add(k);ClientPlayNetworking.send(new ExplorationMapTileRequestPayload(dimension,k.x,k.z));}}
 private void areas(DrawContext c,int l,int t,int r,int b,int cx,int cy){for(var a:areas){if(!a.dimension().equals(dimension))continue;int x=(int)(cx+(a.minChunkX()*16-centerX)*zoom),y=(int)(cy+(a.minChunkZ()*16-centerZ)*zoom),x2=(int)(cx+((a.maxChunkX()+1)*16-centerX)*zoom),y2=(int)(cy+((a.maxChunkZ()+1)*16-centerZ)*zoom);x=Math.max(l,x);y=Math.max(t,y);x2=Math.min(r,x2);y2=Math.min(b,y2);if(x2>x&&y2>y){c.fill(x,y,x2,y2,0x48FF8A00);c.drawBorder(x,y,x2-x,y2-y,0xFFFF9900);}}}
 private void grid(DrawContext c,int l,int t,int r,int b,int cx,int cy){if(showChunkGrid&&16*zoom>=4)gridLines(c,l,t,r,b,cx,cy,16,0x30303030);if(showRegionGrid&&512*zoom>=4)gridLines(c,l,t,r,b,cx,cy,512,0xA0E0E0E0);}
 private void gridLines(DrawContext c,int l,int t,int r,int b,int cx,int cy,int spacing,int color){int minX=(int)Math.floor(centerX+(l-cx)/zoom),maxX=(int)Math.ceil(centerX+(r-cx)/zoom),minZ=(int)Math.floor(centerZ+(t-cy)/zoom),maxZ=(int)Math.ceil(centerZ+(b-cy)/zoom);for(int x=Math.floorDiv(minX,spacing)*spacing;x<=maxX;x+=spacing){int sx=(int)Math.floor(cx+(x-centerX)*zoom);if(sx>=l&&sx<r)c.fill(sx,t,sx+1,b,color);}for(int z=Math.floorDiv(minZ,spacing)*spacing;z<=maxZ;z+=spacing){int sy=(int)Math.floor(cy+(z-centerZ)*zoom);if(sy>=t&&sy<b)c.fill(l,sy,r,sy+1,color);}}
 @Override public boolean mouseClicked(double x,double y,int button){if(button==0&&x>=10&&x<width-10&&y>=28&&y<height-36){dragging=true;lastX=x;lastY=y;return true;}return super.mouseClicked(x,y,button);}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(dragging&&button==0){centerX-=(x-lastX)/zoom;centerZ-=(y-lastY)/zoom;lastX=x;lastY=y;return true;}return super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean mouseReleased(double x,double y,int button){if(button==0&&dragging){dragging=false;return true;}return super.mouseReleased(x,y,button);}
 @Override public boolean mouseScrolled(double x,double y,double h,double v){if(v==0)return false;int cx=width/2,cy=(28+height-36)/2;double old=zoom;zoom=Math.max(.0625,Math.min(16,zoom*Math.pow(1.18,v)));centerX+=(x-cx)*(1/old-1/zoom);centerZ+=(y-cy)*(1/old-1/zoom);return true;}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(key==32){centerX=centerZ=0;zoom=1;return true;}if(key==70&&client.player!=null){centerX=client.player.getBlockX();centerZ=client.player.getBlockZ();return true;}return super.keyPressed(key,scan,modifiers);}
 @Override public boolean shouldPause(){return false;} @Override public void close(){clear();client.setScreen(null);} private void clear(){if(client!=null)for(Identifier id:tiles.values())client.getTextureManager().destroyTexture(id);tiles.clear();requested.clear();} private record Key(String dimension,int x,int z){}
}
